/// Hash-assisted median: groups duplicates via HashMap before selection.
pub fn hash_assisted_median(arr: &[i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    let mut seen: std::collections::HashMap<i32, i64> = std::collections::HashMap::new();
    for &x in arr {
        *seen.entry(x).or_insert(0) += 1;
