//! - For inputs WITH duplicates: reduces to selecting among U unique keys
//!   -> U comparisons where U <= n; if U << n, linear speedup
//! - Asymptotic comparison count unchanged: Theta(n) either way

/// Quickselect (Hoare randomized two-way partition).
pub fn quickselect(arr: &mut Vec<i32>, k: usize) {
    let mut lo = 0;
    let mut hi = arr.len() - 1;
    while lo <= hi {
        let pivot_idx = lo + rand_usize(hi - lo);
        arr.swap(lo, pivot_idx);
        let pivot = arr[lo];
        let mut i = lo;
        let mut j = hi + 1;
        loop {
            i += 1;
            while i <= hi && arr[i] < pivot { i += 1; }
            j -= 1;
            while arr[j] > pivot { j -= 1; }
            if i >= j { break; }
            arr.swap(i, j);
        }
        arr.swap(lo, j);
        if j == k { return; }
        else if j < k { lo = j + 1; }
        else { hi = j - 1; }
    }
}

/// Deterministic selection: median-of-medians pivot (groups of 5).
fn select_mom(arr: &mut [i32], k: usize) -> i32 {
    if arr.len() <= 5 {
        arr.sort_unstable();
        return arr[k];
    }
    let mut medians = Vec::with_capacity(arr.len() / 5 + 1);
    for chunk in arr.chunks(5) {
        let mut grp = Vec::from(chunk);
        grp.sort_unstable();
        medians.push(grp[grp.len() / 2]);
    }
    let pivot = select_mom(&mut medians, medians.len() / 2);
    let mut lt: Vec<i32> = Vec::new();
    let mut eq: Vec<i32> = Vec::new();
    let mut gt: Vec<i32> = Vec::new();
    for x in arr.iter() {
        let v = *x;
        if v < pivot { lt.push(v); }
        else if v == pivot { eq.push(v); }
        else { gt.push(v); }
    }
    match k.cmp(&lt.len()) {
        std::cmp::Ordering::Less => lt[k],
        std::cmp::Ordering::Equal => eq[0],
        std::cmp::Ordering::Greater => select_mom(&mut gt, k - lt.len() - eq.len()),
    }
}

pub fn deterministic_median(arr: &mut [i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    assert!(arr.len() % 2 == 1, "n must be odd");
    Some(select_mom(arr, arr.len() / 2))
}

/// Deterministic pseudo-random integer in [0, range_max).
fn rand_usize(range_max: usize) -> usize {
    static mut SEED: u64 = 42;
    unsafe {
        SEED = SEED.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        ((SEED >> 33) as usize) % range_max
    }
}

/// Hash-assisted median: collapse duplicates before selection.
pub fn hash_assisted_median(arr: &[i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    let mut seen: std::collections::HashMap<i32, i64> = std::collections::HashMap::new();
    for x in arr.iter() {
        *seen.entry(*x).or_insert(0) += 1;
    }
    let mut uniques: Vec<i32> = seen.keys().copied().collect();
    uniques.sort_unstable();
    let target = arr.len() / 2;
    let mut cum: i64 = 0;
    for v in &uniques {
        cum += seen[v];
        if cum > target as i64 { return Some(*v); }
    }
    None
}

