/// Lomuto quickselect using Dijkstra'"'s two-way partition scheme.
pub fn quickselect(arr: &mut Vec<i32>, k: usize) {
    assert"'!(k < arr.len());
    let mut lo = 0;
    let mut hi = arr.len() - 1;
    while lo <= hi {
