        let pidx = rng_shuffle(lo, hi);
        arr.swap(lo, pidx);
        let pivot = arr[lo];

        // Dijkstra two-way partition
        let mut i = lo;
        let mut j = hi + 1;
        loop {
            i += 1;
            while i <= hi && arr[i] < pivot { i += 1; }
            j -= 1;
            while arr[j] > pivot { j -= 1; }
