//! ## Hash-Auxiliated Strategy
//!
//! If equality tests cost epsilon << 1 vs comparisons:
//! - Pre-group via hash table: O(n) time, O(n) cheap equalities
//! - For DISTINCT integers: hashing provides zero benefit
//!   -> still 3n + o(n) comparisons (Theta(n) either way)
//! - For inputs WITH duplicates: reduces to selecting among U unique keys
//!   -> Theta(U) comparisons where U <= n; if U << n, linear speedup

/// Quickselect using Dijkstra'"'s two-way partition scheme.
/// Caller should pre-shuffle the array for randomized performance.
pub fn quickselect(arr: &mut Vec<i32>, k: usize) {
    assert"'!(k < arr.len());
    let mut lo = 0;
    let mut hi = arr.len() - 1;
    while lo <= hi {
        // Pivot = arr[lo] — caller should shuffle beforehand
        let pivot = arr[lo];

        // Dijkstra two-way partition around pivot = arr[lo]
        let mut i = lo;
        let mut j = hi + 1;
        loop {
            i += 1;
            while i <= hi && arr[i] < pivot { i += 1; }
            j -= 1;
            while arr[j] > pivot { j -= 1; }
            if i >= j { break; }
            arr.swap(i, j);
        }
        arr.swap(lo, j);

        if j == k { return; }
        else if j < k { lo = j + 1; }
        else { hi = j - 1; }
    }
}

/// Deterministic selection: median-of-medians pivot (groups of 5).
fn select_mom(arr: &mut [i32], k: usize) -> i32 {
    if arr.len() <= 5 {
        arr.sort_unstable();
        return arr[k];
    }
    let mut medians = Vec::with_capacity(arr.len() / 5 + 1);
    for chunk in arr.chunks(5) {
        let mut grp = Vec::from(chunk);
        grp.sort_unstable();
        medians.push(grp[grp.len() / 2]);
    }
    let mid = medians.len() / 2;
    let pivot = select_mom(&mut medians, mid);
    let mut lt: Vec<i32> = Vec::new();
    let mut eq: Vec<i32> = Vec::new();
    let mut gt: Vec<i32> = Vec::new();
    for x in arr.iter() {
        let v = *x;
        if v < pivot { lt.push(v); }
        else if v == pivot { eq.push(v); }
        else { gt.push(v); }
    }
    match k.cmp(&lt.len()) {
        std::cmp::Ordering::Less => lt[k],
        std::cmp::Ordering::Equal => eq[0],
        std::cmp::Ordering::Greater => select_mom(&mut gt, k - lt.len() - eq.len()),
    }
}

pub fn deterministic_median(arr: &mut [i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    assert!(arr.len() % 2 == 1, "n must be odd");
    Some(select_mom(arr, arr.len() / 2))
}

