/// Deterministic selection: median-of-medians pivot (groups of 5),
/// combined with recursive quickselect on the chosen side.
fn select_mom(arr: &mut [i32], k: usize) -> i32 {
    if arr.len() <= 5 {
        arr.sort_unstable();
        return arr[k];
    }
    // Step 1: Find approximate median via groups-of-5 median-of-medians
    let mut medians = Vec::with_capacity(arr.len() / 5 + 1);
    for chunk in arr.chunks(5) {
        let mut grp = Vec::from(chunk);
        grp.sort_unstable();
        medians.push(grp[grp.len() / 2]);
    }
    let mid = medians.len() / 2;
    let pivot = select_mom(&mut medians, mid);

    // Step 2: Three-way partition around pivot
    let mut lt: Vec<i32> = Vec::new();
    let mut eq: Vec<i32> = Vec::new();
    let mut gt: Vec<i32> = Vec::new();
    for x in arr.iter() {
        let v = *x;
        if v < pivot { lt.push(v); }
        else if v == pivot { eq.push(v); }
        else { gt.push(v); }
    }

    // Step 3: Recurse into the correct side
    match k.cmp(&lt.len()) {
        std::cmp::Ordering::Less => select_mom(&mut lt, k),
        std::cmp::Ordering::Equal => eq[0],
        std::cmp::Ordering::Greater => {
            select_mom(&mut gt, k - lt.len() - eq.len())
        }
    }
}

pub fn deterministic_median(arr: &mut [i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    assert!(arr.len() % 2 == 1, "n must be odd");
    Some(select_mom(arr, arr.len() / 2))
}

// --- Deterministic PRNG (thread-local) for shuffling in tests ---

use std::cell::RefCell;
thread_local! {
    static RNG_STATE: RefCell<u64> = RefCell::new(42);
}

/// Fisher-Yates shuffle using deterministic PRNG.
pub fn shuffle_vec(v: &mut Vec<i32>) {
    RNG_STATE.with(|state| {
        let mut s = state.borrow_mut();
        for i in (1..v.len()).rev() {
            *s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let r = (*s >> 33) as usize;
            v.swap(i, r % (i + 1));
        }
    });
}

/// Reset PRNG state between independent shuffle calls.
pub fn reset_rng() {
    RNG_STATE.with(|state| { *state.borrow_mut() = 42; });
}

/// Hash-assisted median: collapse duplicates before selection.
pub fn hash_assisted_median(arr: &[i32]) -> Option<i32> {
    if arr.is_empty() { return None; }
    let mut seen: std::collections::HashMap<i32, i64> = std::collections::HashMap::new();
    for x in arr.iter() {
        *seen.entry(*x).or_insert(0) += 1;
    }
    let mut uniques: Vec<i32> = seen.keys().copied().collect();
    uniques.sort_unstable();
    let target = arr.len() / 2;
    let mut cum: i64 = 0;
    for v in &uniques {
        cum += seen[v];
        if cum > target as i64 { return Some(*v); }
    }
    None
}

